parameters.jsCode:
const jobs = $input.all();

return jobs.map(item => {
  const job = item.json;

  return {
    json: {
      source: "lever",
      source_id: job.id,

      title: job.text ?? null,
      company: "SFEIR",

      location: job.categories?.location ?? null,
      team: job.categories?.team ?? null,
      contract_type: job.categories?.commitment ?? null,

      description: job.descriptionPlain ?? null,

      job_url: job.hostedUrl ?? null,
      apply_url: job.applyUrl ?? null,

      collected_at: new Date().toISOString()
    }
  };
});

const raw = $json.content?.parts?.[0]?.text;

if (!raw) {
  throw new Error("Gemini returned an empty response.");
}

let analysis;

try {
  analysis = JSON.parse(raw);
} catch (error) {
  throw new Error(`Invalid JSON returned by Gemini: ${raw}`);
}

// Retrieve the original job linked to the current Gemini item
const job = $("Loop Over Items").item.json;

return {
  json: {
    job: {
      source: job.source,
      source_id: job.source_id,
      title: job.title,
      company: job.company,
      location: job.location,
      team: job.team,
      contract_type: job.contract_type,
      description: job.description,
      job_url: job.job_url,
      apply_url: job.apply_url,
      collected_at: job.collected_at
    },

    analysis: {
      ai_automation_relevance:
        Number(analysis.ai_automation_relevance ?? 0),

      junior_compatibility:
        Number(analysis.junior_compatibility ?? 0),

      candidate_fit:
        Number(analysis.candidate_fit ?? 0),

      hidden_ai_automation_role:
        analysis.hidden_ai_automation_role === true,

      matched_skills:
        Array.isArray(analysis.matched_skills)
          ? analysis.matched_skills
          : [],

      missing_skills:
        Array.isArray(analysis.missing_skills)
          ? analysis.missing_skills
          : [],

      experience_required:
        analysis.experience_required ?? "Not explicitly specified",

      reason:
        analysis.reason ?? "",

      recommendation:
        analysis.recommendation ?? "REVIEW"
    }
  }
};

